func TestEnumLeaderboardResponseWithRankingsStatus(t *testing.T) {
	t.Run("NewFromString_active", func(t *testing.T) {
		t.Parallel()
		val, err := NewLeaderboardResponseWithRankingsStatusFromString("active")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, LeaderboardResponseWithRankingsStatus("active"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_scheduled", func(t *testing.T) {
		t.Parallel()
		val, err := NewLeaderboardResponseWithRankingsStatusFromString("scheduled")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, LeaderboardResponseWithRankingsStatus("scheduled"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_finished", func(t *testing.T) {
		t.Parallel()
		val, err := NewLeaderboardResponseWithRankingsStatusFromString("finished")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, LeaderboardResponseWithRankingsStatus("finished"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewLeaderboardResponseWithRankingsStatusFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewLeaderboardResponseWithRankingsStatusFromString("active")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

